"""Turn the built MSIX package and its certificate into a C++ source file.

This is the C++ counterpart of the Python build's inline
"zlib + base64 -> pdfcomp/_shell_payload.py" step. The generated file is

    <repo>/src/shell_payload.cpp

and it defines exactly the two symbols declared in src/shell_payload.hpp:

    pdfc::kShellMsixHex
    pdfc::kShellCerHex

Why hexadecimal strings instead of a C byte array or base64+zlib:

  * a hex string is pure ASCII, so the generated translation unit cannot trip
    over MSVC's source-charset detection, whatever the machine's code page is;
  * decoding it at run time is a table lookup, so the program needs no zlib
    and no base64 dependency of its own;
  * the cost is size (2x instead of base64's 1.33x), which is irrelevant for a
    package that is a few hundred kilobytes.

Keep this file ASCII-only: it is invoked as `python shell\\make_payload.py`
from build_shell_menu.bat.

Usage:
    python shell/make_payload.py <package.msix> <package.cer> <output.cpp>
"""

import os
import sys

# Names must match src/shell_payload.hpp.
MSIX_SYMBOL = "kShellMsixHex"
CER_SYMBOL = "kShellCerHex"

# 96 hex digits = 48 bytes per source line. Long enough to keep the file small,
# short enough to stay readable if someone opens it.
CHUNK = 96

HEADER = """// -*- coding: utf-8 -*-
//
// Generated by shell/build_shell_menu.bat (shell/make_payload.py) -- do not edit.
// This file is a build product: it is in .gitignore and must never be committed,
// because it contains a freshly generated certificate and a signed package.
//
// Two hexadecimal strings, declared in src/shell_payload.hpp.

#include "shell_payload.hpp"

namespace pdfc {
"""

FOOTER = """}  // namespace pdfc
"""


def cpp_literal(data):
    """Render bytes as a C++ string literal, wrapped across lines if long."""
    digits = data.hex()
    if not digits:
        return '""'
    pieces = [digits[i:i + CHUNK] for i in range(0, len(digits), CHUNK)]
    if len(pieces) == 1:
        return '"' + pieces[0] + '"'
    # Adjacent string literals are concatenated by the compiler.
    return "\n" + "\n".join('    "%s"' % piece for piece in pieces)


def main(argv):
    if len(argv) != 4:
        sys.stderr.write(__doc__)
        return 2

    msix_path, cer_path, output_path = argv[1], argv[2], argv[3]
    for path in (msix_path, cer_path):
        if not os.path.isfile(path):
            sys.stderr.write("[ERR] missing input file: %s\n" % path)
            return 1

    with open(msix_path, "rb") as handle:
        msix = handle.read()
    with open(cer_path, "rb") as handle:
        cer = handle.read()

    text = [HEADER]
    text.append("const char* %s =" % MSIX_SYMBOL)
    text.append("%s;" % cpp_literal(msix))
    text.append("")
    text.append("const char* %s =" % CER_SYMBOL)
    text.append("%s;" % cpp_literal(cer))
    text.append("")
    text.append(FOOTER)

    # Newline is forced to LF so the file is identical on every machine.
    with open(output_path, "w", encoding="ascii", newline="\n") as handle:
        handle.write("\n".join(text))

    sys.stdout.write("    payload: %s (%d bytes, msix %d, cer %d)\n"
                     % (output_path, os.path.getsize(output_path), len(msix), len(cer)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
